from azure.cosmos import CosmosClient

def get_client():
    return CosmosClient('https://<your-cosmosdb-instance>.documents.azure.com:443/', credential='<your-cosmosdb-key>')

if __name__ == '__main__':
    client = get_client()

class Document:
    def __init__(self, id, name):
        self.id = id
        self.name = name

    def to_dict(self):
        return {'id': self.id, 'name': self.name}

    @staticmethod
    def from_dict(data):
        return Document(data['id'], data['name'])

def summarize_records(records):
    summary = {}
    for record in records:
        if record['name'] in summary:
            summary[record['name']] += 1
        else:
            summary[record['name']] = 1
    return summary

if __name__ == '__main__':
    records = [{'name': 'John Doe'}, {'name': 'Jane Doe'}, {'name': 'John Doe'}]
    print(summarize_records(records))

import re

def check_safety(text):
    if re.search(r'[^a-zA-Z0-9\s]', text):
        return False
    return True

if __name__ == '__main__':
    print(check_safety('Hello World!'))

import boto3

def export_archive(bucket_name, key, file_path):
    s3 = boto3.client('s3')
    s3.upload_file(file_path, bucket_name, key)

if __name__ == '__main__':
    export_archive('my-bucket', 'my-key', 'my-file.txt')
